from pathlib import Path


def replace_once(path, old, new):
    p=Path(path); s=p.read_text()
    if old not in s: raise SystemExit(f'missing pattern in {path}: {old[:120]!r}')
    p.write_text(s.replace(old,new,1))

# Free access is neither trial nor paid. Respect plan server class/restrictions,
# but do not require the server to be marked paid-enabled for a zero-cost plan.
p='src/jellyfin/provisioning-core.js'
replace_once(p,
"    const isTrial = plan.billing_interval === 'trial';\n",
"    const isTrial = plan.billing_interval === 'trial';\n    const accessKind = isTrial ? 'trial' : (Number(plan.price_minor || 0) === 0 ? 'free' : 'paid');\n")
replace_once(p,
"          AND CASE WHEN $2::boolean THEN js.trial_enabled ELSE js.paid_enabled END\n",
"          AND CASE WHEN $2::text='trial' THEN js.trial_enabled WHEN $2::text='free' THEN TRUE ELSE js.paid_enabled END\n")
replace_once(p,
"    `, [plan.server_class, isTrial, planId, healthMode]);\n",
"    `, [plan.server_class, accessKind, planId, healthMode]);\n")

