# Customer portal: admin-style sidebar, explicit provisioning state, and a large
# post-claim access onboarding overlay containing URL + username when ready.
p='views/customer/dashboard.ejs'
s=Path(p).read_text()
old="""<div class=\"portalShell\">\n  <header class=\"portalTopbar\"><div class=\"brandLockup\"><img class=\"brandLogo\" src=\"/branding/logo\" alt=\"\"><div><div class=\"brandName\"><%= siteName %></div><div class=\"brandMeta\">Customer portal</div></div></div><div class=\"portalActions\"><span class=\"signedIn\">Signed in as <strong><%= username %></strong></span><a class=\"button secondary small\" href=\"/account/security\">Security</a><a class=\"button secondary small\" href=\"/account/history\">Billing history</a><form method=\"post\" action=\"/account/logout\"><input type=\"hidden\" name=\"_csrf\" value=\"<%= csrfToken %>\"><button class=\"button ghost small\" type=\"submit\">Sign out</button></form></div></header>\n\n  <main class=\"portalMain\">\n"""
new="""<div class=\"portalShell\">\n  <header class=\"portalTopbar\"><div class=\"portalTopbarInner\"><div class=\"brandLockup\"><img class=\"brandLogo\" src=\"/branding/logo\" alt=\"\"><div><div class=\"brandName\"><%= siteName %></div><div class=\"brandMeta\">Customer portal</div></div></div><div class=\"portalActions\"><span class=\"signedIn\">Signed in as <strong><%= username %></strong></span><form method=\"post\" action=\"/account/logout\"><input type=\"hidden\" name=\"_csrf\" value=\"<%= csrfToken %>\"><button class=\"button ghost small\" type=\"submit\">Sign out</button></form></div></div></header>\n  <div class=\"customerLayout\">\n    <aside class=\"customerSidebar\" aria-label=\"Customer navigation\">\n      <div class=\"customerNavTitle\">My account</div>\n      <a class=\"customerNavLink active\" href=\"/account\"><span>Overview</span></a>\n      <a class=\"customerNavLink\" href=\"#jellyfin-access\"><span>Jellyfin access</span></a>\n      <% if(hasStremio){ %><a class=\"customerNavLink\" href=\"/account/stremio\"><span>Stremio</span></a><% } %>\n      <a class=\"customerNavLink\" href=\"#plans\"><span>Plans & access</span></a>\n      <a class=\"customerNavLink\" href=\"/account/history\"><span>Billing history</span></a>\n      <a class=\"customerNavLink\" href=\"/account/communications\"><span>Notifications</span></a>\n      <a class=\"customerNavLink\" href=\"/account/affiliate\"><span>Affiliate programme</span></a>\n      <a class=\"customerNavLink\" href=\"/account/activity\"><span>Activity</span></a>\n      <a class=\"customerNavLink\" href=\"/account/security\"><span>Security</span></a>\n      <% if(overseerrUrl){ %><a class=\"customerNavLink\" href=\"<%= overseerrUrl %>\" target=\"_blank\" rel=\"noopener noreferrer\"><span>Request content ↗</span></a><% } %>\n    </aside>\n    <main class=\"portalMain\">\n"""
if old not in s: raise SystemExit('dashboard shell pattern missing')
s=s.replace(old,new,1)
s=s.replace('<section class="sectionBlock"><div class="sectionHead"><div><h2>Jellyfin access</h2>', '<section class="sectionBlock" id="jellyfin-access"><div class="sectionHead"><div><h2>Jellyfin access</h2>',1)
old_empty='<% if(!portal.accounts.length){ %><div class="empty">Your Jellyfin account is not provisioned yet. The provisioning system will keep retrying when capacity is available.</div><% } %>'
new_empty='''<% if(!portal.accounts.length){ %><div class="provisioningPanel <%= provisioningState&&provisioningState.status==='failed'?'failed':'pending' %>"><div><strong>Jellyfin setup <%= provisioningState&&provisioningState.status==='failed'?'needs attention':'is in progress' %></strong><p><%= provisioningState&&provisioningState.last_error?provisioningState.last_error:'Your plan is active, but your Jellyfin user has not been created yet.' %></p><% if(provisioningState&&provisioningState.next_attempt_at){ %><small>Automatic retry: <%= formatDateTime(provisioningState.next_attempt_at) %></small><% } %></div><form method="post" action="/account/provisioning/retry"><input type="hidden" name="_csrf" value="<%= csrfToken %>"><button class="button primary" type="submit">Retry setup now</button></form></div><% } %>'''
if old_empty not in s: raise SystemExit('dashboard empty provisioning pattern missing')
s=s.replace(old_empty,new_empty,1)
# Big onboarding overlay immediately after main opens.
marker='''    <% if (message) { %><div class="notice success"><%= message %></div><% } %>\n    <% if (error) { %><div class="notice error"><%= error %></div><% } %>\n'''
overlay='''    <% if (message) { %><div class="notice success"><%= message %></div><% } %>\n    <% if (error) { %><div class="notice error"><%= error %></div><% } %>\n    <% if(welcome&&currentPlan){ %><div class="accessWelcomeBackdrop"><section class="accessWelcomeModal"><div class="welcomeSuccessIcon"><%= primaryAccount?'✓':'…' %></div><div class="eyebrow"><%= primaryAccount?'Access ready':'Access claimed' %></div><h1><%= primaryAccount?'You now have Jellyfin access':'We are creating your Jellyfin account' %></h1><% if(primaryAccount){ %><p>Your account has been created on <strong><%= primaryAccount.server_name %></strong>. Save these details.</p><div class="credentialGrid"><div><span>Server</span><strong><%= primaryAccount.public_url||'Available from your account' %></strong></div><div><span>Username</span><strong><%= primaryAccount.jellyfin_username %></strong></div><div><span>Password</span><strong><%= primaryAccount.password_setup_required?'Choose your password below':'Your existing Jellyfin password' %></strong></div></div><div class="welcomeActions"><a class="button primary" href="#jellyfin-access">Set up / manage password</a><% if(primaryAccount.public_url&&!primaryAccount.password_setup_required){ %><a class="button free" href="<%= primaryAccount.public_url %>" target="_blank" rel="noopener noreferrer">Open Jellyfin</a><% } %><a class="button secondary" href="/account">Continue to account</a></div><% } else { %><p>Your Free Access entitlement is active, but Jellyfin provisioning has not completed yet.</p><% if(provisioningState&&provisioningState.last_error){ %><div class="welcomeError"><%= provisioningState.last_error %></div><% } %><form method="post" action="/account/provisioning/retry"><input type="hidden" name="_csrf" value="<%= csrfToken %>"><button class="button primary full" type="submit">Retry Jellyfin setup now</button></form><a class="button secondary full" href="/account">Continue while setup retries</a><% } %></section></div><% } %>\n'''
if marker not in s: raise SystemExit('dashboard notice marker missing')
s=s.replace(marker,overlay,1)
s=s.replace('''  </main>\n</div>\n</body>''','''    </main>\n  </div>\n</div>\n</body>''',1)
Path(p).write_text(s)

# Extend existing portal stylesheet instead of creating a second visual system.
