s += '''\n/* Customer app shell + acquisition onboarding */\n.customerLayout{width:min(1420px,calc(100% - 30px));margin:0 auto;display:grid;grid-template-columns:220px minmax(0,1fr);gap:24px}.customerLayout .portalMain{width:100%;margin:0;padding:28px 0 64px}.customerSidebar{position:sticky;top:88px;align-self:start;padding:13px;background:#10161d;border:1px solid var(--line);border-radius:11px}.customerNavTitle{padding:7px 9px 10px;color:#748295;font-size:10px;font-weight:850;letter-spacing:.1em;text-transform:uppercase}.customerNavLink{display:flex;min-height:38px;align-items:center;padding:8px 10px;margin:2px 0;border:1px solid transparent;border-radius:7px;color:#aeb9c6;text-decoration:none;font-size:12px;font-weight:700}.customerNavLink:hover{background:#171f28;color:#edf2f7}.customerNavLink.active{border-color:#27667a;background:rgba(32,169,214,.11);color:#8dddf5}.provisioningPanel{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:18px;border:1px solid rgba(234,182,90,.3);border-radius:10px;background:rgba(234,182,90,.07)}.provisioningPanel.failed{border-color:rgba(224,108,117,.32);background:rgba(224,108,117,.07)}.provisioningPanel strong{font-size:14px}.provisioningPanel p{margin:5px 0;color:#b3bdc8;line-height:1.45}.provisioningPanel small{color:#7e8a9a}.accessWelcomeBackdrop{position:fixed;z-index:1000;inset:0;display:grid;place-items:center;padding:22px;background:rgba(4,8,12,.82);backdrop-filter:blur(10px)}.accessWelcomeModal{width:min(680px,100%);padding:34px;border:1px solid #315160;border-radius:16px;background:#121a22;box-shadow:0 30px 100px rgba(0,0,0,.55)}.welcomeSuccessIcon{display:grid;place-items:center;width:58px;height:58px;margin-bottom:18px;border-radius:50%;background:rgba(53,201,135,.13);border:1px solid rgba(53,201,135,.35);color:#70dfad;font-size:30px;font-weight:900}.accessWelcomeModal h1{margin:8px 0 8px;font-size:30px;letter-spacing:-.025em}.accessWelcomeModal>p{color:#aeb9c6;line-height:1.55}.credentialGrid{display:grid;gap:8px;margin:22px 0}.credentialGrid>div{display:grid;grid-template-columns:100px 1fr;gap:14px;padding:12px 13px;border:1px solid var(--line);border-radius:8px;background:#0d141b}.credentialGrid span{color:#748295;font-size:10px;text-transform:uppercase;font-weight:800;letter-spacing:.08em}.credentialGrid strong{overflow-wrap:anywhere}.welcomeActions{display:flex;gap:8px;flex-wrap:wrap;margin-top:20px}.welcomeError{margin:15px 0;padding:12px;border:1px solid rgba(224,108,117,.35);border-radius:8px;background:rgba(224,108,117,.08);color:#f0afb4}.accessWelcomeModal>.button.full{margin-top:8px}@media(max-width:900px){.customerLayout{grid-template-columns:1fr}.customerSidebar{position:static;display:flex;overflow-x:auto;gap:4px;padding:8px}.customerNavTitle{display:none}.customerNavLink{white-space:nowrap;flex:0 0 auto}.customerLayout .portalMain{padding-top:8px}}@media(max-width:600px){.signedIn{display:none}.accessWelcomeModal{padding:24px 19px}.accessWelcomeModal h1{font-size:24px}.credentialGrid>div{grid-template-columns:1fr;gap:4px}.provisioningPanel{align-items:stretch;flex-direction:column}}\n'''
Path(p).write_text(s)

# Permanent static regression guard.
Path('scripts/free-access-customer-portal-smoke.js').write_text(r'''\n'use strict';\nconst assert=require('assert');const fs=require('fs');\nconst provision=fs.readFileSync('src/jellyfin/provisioning-core.js','utf8');\nconst dash=fs.readFileSync('src/platform/customer-dashboard.js','utf8');\nconst view=fs.readFileSync('views/customer/dashboard.ejs','utf8');\nassert(/accessKind\s*=\s*isTrial\s*\?\s*['\"]trial['\"]/.test(provision),'placement must classify trial/free/paid');\nassert(/\$2::text='free'\s+THEN TRUE/.test(provision),'free access must not require paid_enabled');\nassert(/getCustomerState\(req\.session\.customerId\)/.test(dash),'customer dashboard must expose provisioning state');\nassert(/\/account\/provisioning\/retry/.test(dash),'customer must have provisioning retry route');\nassert(/customerSidebar/.test(view)&&/Notifications/.test(view)&&/Affiliate programme/.test(view)&&/Security/.test(view),'customer left navigation missing');\nassert(/accessWelcomeBackdrop/.test(view)&&/You now have Jellyfin access/.test(view),'large access onboarding modal missing');\nassert(/primaryAccount\.public_url/.test(view)&&/primaryAccount\.jellyfin_username/.test(view),'onboarding must show server URL and Jellyfin username');\nassert(/provisioningState\.last_error/.test(view),'customer provisioning failure reason missing');\nconsole.log('free access customer portal smoke: ok');\n'''.lstrip())

